// Research-led mobile helpers: inline recovery and unobscured controls.
let uiFieldId=0;
function clearFieldError(input){if(!input?.dataset.uiError)return;const id=input.dataset.uiError;const old=document.getElementById(id);if($('#wizard-error')?.textContent===old?.textContent)$('#wizard-error').textContent='';old?.remove();const refs=(input.getAttribute('aria-describedby')||'').split(/\s+/).filter(x=>x&&x!==id);if(refs.length)input.setAttribute('aria-describedby',refs.join(' '));else input.removeAttribute('aria-describedby');input.removeAttribute('aria-invalid');delete input.dataset.uiError;}
function fieldError(input,message){if(!input)return;clearFieldError(input);if(!input.id)input.id='ui-field-'+(++uiFieldId);const error=document.createElement('span');error.id=input.id+'-error';error.className='ui-field-error';error.textContent=message;input.before(error);input.dataset.uiError=error.id;input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',((input.getAttribute('aria-describedby')||'')+' '+error.id).trim());input.focus({preventScroll:true});requestAnimationFrame(()=>keepVisible(input));}
function keepVisible(target){if(!target?.isConnected)return;const r=target.getBoundingClientRect(),viewport=window.visualViewport,top=(viewport?.offsetTop||0)+($('.topbar')?.getBoundingClientRect().height||0)+12,bottom=(viewport?.offsetTop||0)+(viewport?.height||innerHeight)-(mobileQuery.matches?$('.wizard-bottom')?.getBoundingClientRect().height||0:0)-16;if(r.top<top||r.bottom>bottom)window.scrollBy({top:r.top-Math.max(top,(top+bottom-r.height)/2),behavior:'instant'});}
function viewportLayout(){const viewport=window.visualViewport,height=viewport?.height||innerHeight,offset=viewport?.offsetTop||0,keyboard=Math.max(0,innerHeight-height-offset),root=document.documentElement;root.style.setProperty('--ui-keyboard-offset',keyboard+'px');root.style.setProperty('--ui-header-height',($('.topbar')?.getBoundingClientRect().height||0)+'px');root.style.setProperty('--ui-footer-height',($('.wizard-bottom')?.getBoundingClientRect().height||0)+'px');document.body.classList.toggle('ui-keyboard-open',keyboard>120&&!!document.activeElement?.matches('input,select,textarea'));}
