 if(submit){const action=submit.closest('.wizard-choices')||submit;const marker=document.createComment('guided actions');action.before(marker);saved.push({node:action,marker,hidden:action.hidden});form.append(action);}
 const kept=new Set([header,figure,nav,...parts,submit?.closest('.wizard-choices')||submit]);const quiet=[...form.children].filter(n=>!kept.has(n)&&!(form.id==='opening-form'&&(n.matches('header')||n.classList.contains('opening-velden')))).map(n=>({node:n,hidden:n.hidden}));quiet.forEach(({node})=>node.hidden=true);
