 const original=new Map(inputs.flat().map(n=>[n,n.disabled]));
 function enable(){for(const [n,disabled] of original)n.disabled=disabled;}
 function update(){if(sketch)figure.innerHTML=sketch(index);}
 function show(focus=false){form.querySelectorAll('[data-ui-error]').forEach(clearFieldError);if(form.closest('#wizard')){$('#wizard-error').textContent='';$('#wizard-message').textContent='';}if(form.id==='wizard-size')document.body.classList.toggle('wizard-name-only',index===0);figure.hidden=form.id==='wizard-size'&&index===0;form.dataset.guidedPage=String(index);form.dataset.guidedLast=String(specs.length-1);for(let i=0;i<parts.length;i++){parts[i].hidden=i!==index;for(const n of inputs[i])n.disabled=i!==index||original.get(n);}header.querySelector('p').textContent=`Vraag ${index+1} van ${specs.length}`;header.querySelector('h3').textContent=specs[index].title;if(submit)submit.hidden=index!==parts.length-1;nav.querySelector('[data-guided-back]').disabled=index===0;nav.querySelector('[data-guided-next]').hidden=index===parts.length-1;if(external){$('#wizard-next').textContent=index===parts.length-1?'Deze maten gebruiken':index===0?'Bevestigen en volgende':'Volgende';$('#wizard-back').disabled=index===0;}update();if(changed)changed(index,index===parts.length-1);mobileControls();if(focus){header.querySelector('h3').focus({preventScroll:true});header.scrollIntoView({block:'nearest',behavior:'instant'});}}
 function valid(list){const bad=list.find(n=>!original.get(n)&&!n.validity.valid);if(!bad)return true;const page=inputs.findIndex(ns=>ns.includes(bad));index=Math.max(0,page);show();bad.reportValidity();bad.focus();return false;}
 function advance(){if(form.id==='wizard-size'){const name=form.querySelector('[name=naam]');name.setCustomValidity(name.value.trim()?'':'Vul een naam voor de ruimte in.');}if(!valid(inputs[index]))return true;if(index<parts.length-1){index++;show(true);return true;}enable();if(!valid(inputs.flat()))return true;return false;}
