function pageSize(){const form=$('#wizard-size');if(!form)return;const labels=['naam','lengte','breedte','hoogte'].map(k=>form.querySelector(`[name=${k}]`).closest('label'));labels.slice(1).forEach(l=>{const input=l.querySelector('input');metricButtons(input);input.addEventListener('input',()=>{const n=Number(input.value.replace(',','.'));input.setCustomValidity(n>=.2&&n<=1000?'':'Kies een maat tussen 0,2 en 1000 meter.');});});form.querySelectorAll('p.hint').forEach(n=>n.hidden=true);const summary=document.createElement('p');summary.textContent='Klopt het voorbeeld? Bevestig de maten. Daarna overlopen we elke wand apart.';form.append(summary);const shape=form.querySelector('[data-ruimte-tekenen]');if(locked(actieveRuimte()))for(const label of labels.slice(1)){const note=document.createElement('p');note.className='hint';note.textContent='Deze maat volgt uit de getekende vorm, het schuine vlak of het huisplan. Pas de vorm aan om deze maat te wijzigen.';const button=document.createElement('button');button.type='button';button.className='knop';button.dataset.ruimteTekenen='';button.textContent='Vorm en maten aanpassen';label.append(note,button);}labels[0].firstChild.textContent='Naam van de ruimte';pageForm(form,[{title:'Hoe heet deze ruimte?',nodes:[labels[0]]},{title:'Wat is de lengte?',nodes:[labels[1]]},{title:'Wat is de breedte?',nodes:[labels[2]]},{title:'Wat is de hoogte?',nodes:[labels[3]]},{title:'Klopt je ruimte?',nodes:[summary,shape]}],{external:true,sketch:sizeSketch});}
function itemSketch(){const form=$('#wizard-item'),r=actieveRuimte();if(!form||!r)return '';const floor=!!$('#wizard-ceil-x')||$('#wizard-surface').value==='plafond',f=!floor&&BouwVorm.wallFrame(r,$('#wizard-surface').value);const pts=f?f.quad.map(a=>({x:(a[0]-f.a.x)*f.u[0]+(a[1]-f.a.y)*f.u[1],y:a[2]/f.v[2]})):BouwVorm.points(r);const minX=Math.min(...pts.map(a=>a.x)),minY=Math.min(...pts.map(a=>a.y)),width=Math.max(...pts.map(a=>a.x))-minX,height=Math.max(...pts.map(a=>a.y))-minY,scale=Math.min(280/width,140/height);const project=a=>[30+(a.x-minX)*scale,floor?20+(a.y-minY)*scale:170-(a.y-minY)*scale];let marker='';try{let x=metric($(floor?'#wizard-ceil-x':'#wizard-pos').value),y=metric($(floor?'#wizard-ceil-y':'#wizard-height').value);if(f){place(r,f.id,x,y);y/=f.v[2];}else if(!BouwVorm.inside(r,{x,y}))throw Error();const a=project({x,y});marker=`<circle class="point-dot" cx="${a[0]}" cy="${a[1]}" r="9"/>`;}catch{}const area=!$('#wizard-quantity');return `<svg viewBox="0 0 340 220" ${area?'role="img"':'class="guided-item-pick" tabindex="0" role="group"'} aria-label="${area?'Gekozen werkvlak':'Tik op het werkvlak om de plaats te kiezen'}"><polygon class="point-wall ${area?'guided-covered':''}" points="${pts.map(p=>project(p).join(',')).join(' ')}"/>${BouwContext.svg(r,(x,y,z)=>project(f?{x:(x-f.a.x)*f.u[0]+(y-f.a.y)*f.u[1],y:z/f.v[2]}:{x,y}),{wall:f?f.id:null})}${marker}<text x="30" y="200">${floor?'Plafond · bovenaanzicht':'Huidige wand · vooraanzicht'} · ${NRL.format(width)} m</text></svg><p class="hint">${area?'Het gekleurde vlak wordt begroot; openingen en netto-oppervlakte worden door de berekening bepaald.':'Bevestigd: groen · voorstel: blauw. Tik om de nieuwe plaats te kiezen; pas bevestigen voegt iets toe.'}</p>`;}
function pickItem(e){const svg=e.target.closest('.guided-item-pick');if(!svg||!selection)return;const r=actieveRuimte(),floor=!!$('#wizard-ceil-x'),f=!floor&&BouwVorm.wallFrame(r,$('#wizard-surface').value);const pts=f?f.quad.map(a=>({x:(a[0]-f.a.x)*f.u[0]+(a[1]-f.a.y)*f.u[1],y:a[2]/f.v[2]})):BouwVorm.points(r),minX=Math.min(...pts.map(p=>p.x)),minY=Math.min(...pts.map(p=>p.y)),width=Math.max(...pts.map(p=>p.x))-minX,height=Math.max(...pts.map(p=>p.y))-minY,scale=Math.min(280/width,140/height),q=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse()),x=minX+(q.x-30)/scale,y=minY+(floor?q.y-20:170-q.y)/scale;try{if(f)place(r,f.id,x,y*f.v[2]);else if(!BouwVorm.inside(r,{x,y}))throw Error('Kies een plaats binnen de kamer.');$(floor?'#wizard-ceil-x':'#wizard-pos').value=Number(x.toFixed(3));$(floor?'#wizard-ceil-y':'#wizard-height').value=Number((floor?y:y*f.v[2]).toFixed(3));$('#wizard-error').textContent='';$('#wizard-item')._guided.update();previewItem();}catch(error){$('#wizard-error').textContent=error.message;}}
function pageItem(p){const form=$('#wizard-item'),labels=id=>$(id)?.closest('label'),pages=[];form.querySelectorAll('p.hint').forEach(n=>n.hidden=true);const q=$('#wizard-quantity'),pos=$('#wizard-pos'),ceil=$('#wizard-ceil-x');if(q){const hint=document.createElement('p');hint.className='hint';hint.textContent=p.eenheid==='m'?'Meet de volledige route. De lijn op de tekening is alleen een schets.':'Verschillende plaatsen? Voeg de toestellen één voor één toe. Bij meerdere stuks in deze post geldt dezelfde schematische plaats.';form.append(hint);pages.push({title:p.eenheid==='m'?'Hoeveel meter is nodig?':'Hoeveel wil je toevoegen?',nodes:[labels('#wizard-quantity'),form.querySelector('.count-buttons'),hint]});if(p.eenheid==='m')metricButtons(q,.5);}if(pos||ceil){const nodes=pos?[labels('#wizard-pos'),labels('#wizard-height')]:[labels('#wizard-ceil-x'),labels('#wizard-ceil-y')];nodes.forEach(l=>metricButtons(l.querySelector('input')));pages.unshift({title:'Waar komt het? Tik op de tekening.',nodes});}else pages.push({title:'Dit hele werkvlak bekleden?',nodes:[labels('#wizard-surface')]});const final=document.createElement('p');final.textContent='Controleer het werkvlak, de hoeveelheid en de prijs. Pas hieronder voeg je dit werk toe.';form.append(final);pages.push({title:'Klopt dit werk en de prijs?',nodes:[final,$('#wizard-item-price')]});if(q)labels('#wizard-surface').hidden=true;pageForm(form,pages,{sketch:itemSketch,changed:(_,last)=>{if(last)selection.previewSnapshot=JSON.stringify(state.project);}});form.addEventListener('click',pickItem);}
